package com.bank.flink.wm;

import java.math.BigDecimal;

// A record in the batch stream: either a normal transaction OR an
// end-of-batch marker that guarantees no more txns for this batch.
class BatchTxn {
    private final String accountId;
    private final BigDecimal amount;
    private final long eventTimeMillis;
    private final boolean endOfBatchMarker;

    private BatchTxn(String accountId, BigDecimal amount, long eventTimeMillis, boolean marker) {
        this.accountId = accountId;
        this.amount = amount;
        this.eventTimeMillis = eventTimeMillis;
        this.endOfBatchMarker = marker;
    }

    static BatchTxn txn(String accountId, BigDecimal amount, long eventTimeMillis) {
        return new BatchTxn(accountId, amount, eventTimeMillis, false);
    }

    static BatchTxn marker(long batchBoundaryMillis) {
        return new BatchTxn("MARKER", BigDecimal.ZERO, batchBoundaryMillis, true);
    }

    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
    long getEventTimeMillis() { return eventTimeMillis; }
    boolean isEndOfBatchMarker() { return endOfBatchMarker; }
}
