package com.bank.flink.wm;

import java.util.logging.Logger;

// Stands in for Flink's WatermarkStrategy. It provides:
//  - a timestamp assigner (reads eventTimeMillis)
//  - a PUNCTUATED watermark generator (advances on markers) combined with
//    bounded-out-of-orderness for normal events.
class CustomWatermarkStrategy {
    private static final Logger log = Logger.getLogger(CustomWatermarkStrategy.class.getName());

    private final long outOfOrdernessMillis;
    private long maxSeen = Long.MIN_VALUE;
    private long currentWatermark = Long.MIN_VALUE;

    CustomWatermarkStrategy(long outOfOrdernessMillis) {
        this.outOfOrdernessMillis = outOfOrdernessMillis;
    }

    // createTimestampAssigner: extract event time from the record.
    long assignTimestamp(BatchTxn txn) {
        return txn.getEventTimeMillis();
    }

    // createWatermarkGenerator.onEvent: track max, punctuate on marker.
    void onEvent(BatchTxn txn) {
        long ts = assignTimestamp(txn);
        if (ts > maxSeen) maxSeen = ts;
        if (txn.isEndOfBatchMarker()) {
            // Punctuated: the marker GUARANTEES completeness up to its time.
            currentWatermark = Math.max(currentWatermark, ts);
            log.info(() -> "MARKER punctuated watermark -> " + currentWatermark);
        } else {
            // Periodic style: max seen minus tolerated out-of-orderness.
            long candidate = maxSeen - outOfOrdernessMillis;
            if (candidate > currentWatermark) currentWatermark = candidate;
        }
    }

    long currentWatermark() { return currentWatermark; }
}
