package com.bank.flink.wm;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Receives events and, using the strategy's watermark, classifies each
// non-marker event as on-time or late (late = already past watermark).
class WatermarkConsumer {
    private static final Logger log = Logger.getLogger(WatermarkConsumer.class.getName());

    private final CustomWatermarkStrategy strategy;
    private final List<BatchTxn> dropped = new ArrayList<>();
    private int accepted = 0;

    WatermarkConsumer(CustomWatermarkStrategy strategy) {
        this.strategy = strategy;
    }

    void consume(BatchTxn txn) {
        long watermarkBefore = strategy.currentWatermark();
        strategy.onEvent(txn);
        if (txn.isEndOfBatchMarker()) return;

        // An event is LATE if its timestamp is at/behind the watermark
        // that existed BEFORE it arrived.
        if (txn.getEventTimeMillis() <= watermarkBefore) {
            dropped.add(txn);
            log.warning(() -> "DROPPED late " + txn.getAccountId()
                    + " ts=" + txn.getEventTimeMillis() + " (watermark=" + watermarkBefore + ")");
        } else {
            accepted++;
            log.info(() -> "ACCEPTED " + txn.getAccountId() + " ts=" + txn.getEventTimeMillis());
        }
    }

    int getAccepted() { return accepted; }
    List<BatchTxn> getDropped() { return dropped; }
}
