package com.bank.flink.wm;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: same stream processed with too-low vs reasonable
// out-of-orderness, plus a punctuated end-of-batch marker.
public class CustomWatermarkDemo {
    private static final Logger log = Logger.getLogger(CustomWatermarkDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new WmLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BatchTxn[] stream = new BatchTxn[] {
            BatchTxn.txn("SAV2001", new BigDecimal("1000.00"), 10_000),
            BatchTxn.txn("CUR3001", new BigDecimal("500.00"),  12_000),
            BatchTxn.txn("SAV2001", new BigDecimal("250.00"),  11_000), // slightly out of order
            BatchTxn.marker(12_000)                                     // end of batch
        };

        log.info(() -> "=== Run A: out-of-orderness = 0 (too low) ===");
        runWith(stream, 0L);

        log.info(() -> "=== Run B: out-of-orderness = 5000 (reasonable) ===");
        runWith(stream, 5_000L);
    }

    private static void runWith(BatchTxn[] stream, long oooMillis) {
        CustomWatermarkStrategy strategy = new CustomWatermarkStrategy(oooMillis);
        WatermarkConsumer consumer = new WatermarkConsumer(strategy);
        for (BatchTxn txn : stream) consumer.consume(txn);
        List<BatchTxn> dropped = consumer.getDropped();
        log.info(() -> "Result: accepted=" + consumer.getAccepted() + " dropped=" + dropped.size());
    }
}

// ─── Would be in WmLogFormatter.java in a real project ───
class WmLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
